{

    internal InnerDataAutomationProjectDocumentOutputTextFormatFactory TextFormatFactory { get; set; }

    internal InnerDataAutomationProjectDocumentOutputAdditionalFileFormatFactory AdditionalFileFormatFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.DocumentOutputFormat Create()
    {
        var documentOutputFormatResult = CreateDocumentOutputFormat();
        factoryAction?.Invoke(documentOutputFormatResult);

        return documentOutputFormatResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.DocumentOutputFormat CreateDocumentOutputFormat()
    {
        var documentOutputFormatResult = new Humidifier.Bedrock.DataAutomationProjectTypes.DocumentOutputFormat();

        return documentOutputFormatResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.DocumentOutputFormat result)
    {
        base.CreateChildren(result);

        result.TextFormat ??= TextFormatFactory?.Build();
        result.AdditionalFileFormat ??= AdditionalFileFormatFactory?.Build();
    }

} // End Of Class

